public class TurnToAngleCommand extends Command {
  private final Drivetrain m_drive;
  private final PIDController m_pid = new PIDController(0.02, 0.0, 0.001);
  private final double m_targetDegrees;

  public TurnToAngleCommand(Drivetrain drive, double targetDegrees) {
    m_drive = drive;
    m_targetDegrees = targetDegrees;
    m_pid.setTolerance(2.0);
    addRequirements(m_drive);
  }

  @Override
  public void execute() {
    double output = m_pid.calculate(m_targetDegrees, m_drive.getHeading());
    m_drive.arcadeDrive(0.0, MathUtil.clamp(output, -0.5, 0.5), false);
  }

  @Override
  public boolean isFinished() {
    return m_pid.atSetpoint();
  }

  @Override
  public void end(boolean interrupted) {
    m_drive.arcadeDrive(0.0, 0.0, false);
  }
}
